import{_ as a,o as s,c as t,ag as i}from"./chunks/framework.CrXGS008.js";const h=JSON.parse('{"title":"Repair Station Business","description":"","frontmatter":{},"headers":[],"relativePath":"fr/repair-station-business/index.md","filePath":"fr/repair-station-business/index.md"}'),n={name:"fr/repair-station-business/index.md"};function r(o,e,l,p,u,c){return s(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="repair-station-business" tabindex="-1">Repair Station Business <a class="header-anchor" href="#repair-station-business" aria-label="Permalink to &quot;Repair Station Business&quot;">​</a></h1><p>L&#39;extension payante de la <a href="/fr/repair-station/">Repair Station</a> : les joueurs achètent des stations de réparation, les approvisionnent en pièces, fixent leurs prix et encaissent la caisse. Tout se gère depuis une tablette à la station, et chaque réglage se modifie en jeu.</p><h2 id="fonctionnalites" tabindex="-1">Fonctionnalités <a class="header-anchor" href="#fonctionnalites" aria-label="Permalink to &quot;Fonctionnalités&quot;">​</a></h2><ul><li><strong>Stations à vendre</strong> : vous choisissez quelles Repair Stations peuvent être achetées et à quel prix. Voir <a href="/fr/repair-station-business/ownership">Propriété</a>.</li><li><strong>Tablette du propriétaire</strong> : stock, caisse, dernières opérations, tarifs, nom et vente de la station, au même endroit.</li><li><strong>Pièces</strong> : chaque réparation consomme des pièces du stock de la station, achetées avec le compte bancaire ou remises sous forme d&#39;objets. Voir <a href="/fr/repair-station-business/stock">Stock</a>.</li><li><strong>Tarifs du propriétaire</strong> : chaque propriétaire fixe un pourcentage du prix de base, dans les limites que vous choisissez, et une taxe est prélevée sur chaque paiement.</li><li><strong>Fins équitables</strong> : un propriétaire qui vend, est expulsé ou devient inactif est remboursé d&#39;une part du prix d&#39;achat plus la caisse, même hors ligne.</li><li><strong>Panneau d&#39;administration</strong> : mettez des stations en vente, changez leur prix, réglez le stock des stations possédées ou expulsez un propriétaire, sans quitter le jeu.</li><li><strong>API HTTP et webhooks</strong> : stations, registre et statistiques pour votre site, et un message Discord pour chaque achat, réapprovisionnement, retrait et perte de station. Voir <a href="/fr/repair-station-business/api">API et webhooks</a>.</li><li><strong>Six langues</strong> : anglais, français, espagnol, portugais, polonais, allemand.</li></ul><h2 id="compatibilite" tabindex="-1">Compatibilité <a class="header-anchor" href="#compatibilite" aria-label="Permalink to &quot;Compatibilité&quot;">​</a></h2><ul><li>Frameworks : ESX Legacy, QBCore, QBox, ox_core, détectés automatiquement.</li><li>Dépendances : oxmysql, <code>nay_lib</code> et la <a href="/fr/repair-station/">Repair Station</a> (<code>nay_repair</code>), fournis avec votre achat des scripts.</li></ul><h2 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h2><div class="language-cfg vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cfg</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ensure oxmysql</span></span>
<span class="line"><span>ensure nay_lib</span></span>
<span class="line"><span>ensure nay_repair</span></span>
<span class="line"><span>ensure nay_repair_business</span></span></code></pre></div><p>Les étapes complètes sont sur la page <a href="/fr/getting-started">Prise en main</a>. Donnez-vous ensuite <code>nay_repair_business.config</code> (ou <code>nay.admin</code>) et ouvrez <code>/nay</code>, ou tapez <code>/nay:repairbusiness</code> pour le panneau d&#39;administration. Marquez dans le panneau les stations que vous voulez vendre : tant que ce n&#39;est pas fait, les stations se comportent comme de simples Repair Stations.</p>`,9)])])}const m=a(n,[["render",r]]);export{h as __pageData,m as default};
